# --- Segurança: RLS, auditoria encadeada, imutabilidade e permissões ----------
# Mantido em SQL explícito nesta migração (e não importado de app/) para que ela
# continue reproduzível mesmo que o código da aplicação mude.

TENANT_TABLES = (
    "audit_log",
    "block",
    "consent",
    "contact",
    "conversation",
    "data_snapshot",
    "handoff",
    "intent",
    "message",
    "privacy_notice",
    "property",
    "rate",
    "search_result",
    "weekly_report",
    "whatsapp_account",
)
RUNTIME_ROLES = "rentaldesk_app, rentaldesk_ops"
GENESIS_HASH = "\\x" + "00" * 32

CURRENT_TENANT_FN = """
CREATE FUNCTION app_current_tenant() RETURNS uuid
LANGUAGE sql STABLE PARALLEL SAFE AS $$
  SELECT NULLIF(current_setting('app.current_tenant_id', true), '')::uuid
$$;
CREATE FUNCTION app_current_user() RETURNS uuid
LANGUAGE sql STABLE PARALLEL SAFE AS $$
  SELECT NULLIF(current_setting('app.current_user_id', true), '')::uuid
$$;
"""

AUDIT_FNS = f"""
CREATE FUNCTION audit_log_digest(
  p_prev bytea, p_tenant uuid, p_seq bigint, p_conversation uuid, p_event text,
  p_snapshot text, p_payload jsonb, p_created timestamptz
) RETURNS bytea LANGUAGE sql IMMUTABLE AS $$
  SELECT sha256(p_prev || convert_to(concat_ws('|',
    p_tenant::text, p_seq::text, coalesce(p_conversation::text, ''), p_event,
    coalesce(p_snapshot, ''), p_payload::text,
    to_char(p_created AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
  ), 'UTF8'))
$$;

CREATE FUNCTION audit_log_chain() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  last_seq bigint;
  last_hash bytea;
BEGIN
  -- Serializa as inclusões do mesmo tenant para a corrente não bifurcar.
  PERFORM pg_advisory_xact_lock(hashtextextended('audit_log:' || NEW.tenant_id::text, 0));
  SELECT seq, hash INTO last_seq, last_hash
    FROM audit_log WHERE tenant_id = NEW.tenant_id ORDER BY seq DESC LIMIT 1;
  NEW.seq := coalesce(last_seq, 0) + 1;
  NEW.prev_hash := coalesce(last_hash, '{GENESIS_HASH}'::bytea);
  NEW.created_at := clock_timestamp();
  NEW.hash := audit_log_digest(NEW.prev_hash, NEW.tenant_id, NEW.seq, NEW.conversation_id,
                               NEW.event_type, NEW.snapshot_hash, NEW.payload, NEW.created_at);
  RETURN NEW;
END $$;

CREATE FUNCTION audit_log_verify(p_tenant uuid) RETURNS bigint
LANGUAGE plpgsql STABLE AS $$
-- Devolve o primeiro `seq` quebrado da corrente do tenant, ou NULL se íntegra.
DECLARE
  r record;
  expected_prev bytea := '{GENESIS_HASH}'::bytea;
  expected_seq bigint := 1;
BEGIN
  FOR r IN SELECT * FROM audit_log WHERE tenant_id = p_tenant ORDER BY seq LOOP
    IF r.seq <> expected_seq OR r.prev_hash <> expected_prev OR r.hash <> audit_log_digest(
         r.prev_hash, r.tenant_id, r.seq, r.conversation_id, r.event_type,
         r.snapshot_hash, r.payload, r.created_at) THEN
      RETURN r.seq;
    END IF;
    expected_prev := r.hash;
    expected_seq := expected_seq + 1;
  END LOOP;
  RETURN NULL;
END $$;

CREATE FUNCTION reject_change() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION '% é somente inclusão: % recusado', TG_TABLE_NAME, TG_OP
    USING ERRCODE = 'insufficient_privilege';
END $$;

CREATE TRIGGER audit_log_chain BEFORE INSERT ON audit_log
  FOR EACH ROW EXECUTE FUNCTION audit_log_chain();
CREATE TRIGGER audit_log_immutable BEFORE UPDATE OR DELETE ON audit_log
  FOR EACH ROW EXECUTE FUNCTION reject_change();
CREATE TRIGGER audit_log_no_truncate BEFORE TRUNCATE ON audit_log
  FOR EACH STATEMENT EXECUTE FUNCTION reject_change();
CREATE TRIGGER privacy_notice_immutable BEFORE UPDATE OR DELETE ON privacy_notice
  FOR EACH ROW EXECUTE FUNCTION reject_change();
"""


def _tenant_policy(table: str) -> str:
    return f"""
ALTER TABLE {table} ENABLE ROW LEVEL SECURITY;
ALTER TABLE {table} FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON {table}
  USING (tenant_id = app_current_tenant())
  WITH CHECK (tenant_id = app_current_tenant());
"""


SPECIAL_POLICIES = """
ALTER TABLE tenant ENABLE ROW LEVEL SECURITY;
ALTER TABLE tenant FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON tenant
  USING (id = app_current_tenant()) WITH CHECK (id = app_current_tenant());

-- Vínculos: a sessão vê os do próprio tenant e os do usuário logado (escolha de
-- imobiliária no login); só altera os do próprio tenant.
ALTER TABLE tenant_member ENABLE ROW LEVEL SECURITY;
ALTER TABLE tenant_member FORCE ROW LEVEL SECURITY;
CREATE POLICY member_read ON tenant_member FOR SELECT
  USING (tenant_id = app_current_tenant() OR user_id = app_current_user());
CREATE POLICY member_write ON tenant_member FOR INSERT
  WITH CHECK (tenant_id = app_current_tenant());
CREATE POLICY member_update ON tenant_member FOR UPDATE
  USING (tenant_id = app_current_tenant()) WITH CHECK (tenant_id = app_current_tenant());
CREATE POLICY member_delete ON tenant_member FOR DELETE
  USING (tenant_id = app_current_tenant());

-- Roteamento: leitura global (webhook ainda não sabe o tenant); escrita só do próprio.
ALTER TABLE tenant_route ENABLE ROW LEVEL SECURITY;
ALTER TABLE tenant_route FORCE ROW LEVEL SECURITY;
CREATE POLICY route_read ON tenant_route FOR SELECT USING (true);
CREATE POLICY route_insert ON tenant_route FOR INSERT
  WITH CHECK (tenant_id = app_current_tenant());
CREATE POLICY route_update ON tenant_route FOR UPDATE
  USING (tenant_id = app_current_tenant()) WITH CHECK (tenant_id = app_current_tenant());
CREATE POLICY route_delete ON tenant_route FOR DELETE
  USING (tenant_id = app_current_tenant());
"""

GRANTS = f"""
-- Os privilégios padrão (deploy/postgres/init-roles.sh) já dão DML aos papéis de
-- execução; aqui ficam as restrições adicionais e as concessões explícitas.
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO {RUNTIME_ROLES};
REVOKE UPDATE, DELETE, TRUNCATE ON audit_log, privacy_notice FROM {RUNTIME_ROLES};
REVOKE INSERT, UPDATE, DELETE ON tenant FROM rentaldesk_app;
GRANT UPDATE (name, paused_at, assistant_name, tone, contact_phone, broker_hours,
              active_snapshot_id, availability_updated_at, status, updated_at)
  ON tenant TO rentaldesk_app;
REVOKE ALL ON alembic_version FROM {RUNTIME_ROLES};
"""


def _upgrade_security() -> None:
    op.execute(CURRENT_TENANT_FN)
    for table in TENANT_TABLES:
        op.execute(_tenant_policy(table))
    op.execute(SPECIAL_POLICIES)
    op.execute(AUDIT_FNS)
    op.execute(GRANTS)


def _downgrade_security() -> None:
    op.execute(
        """
DROP TRIGGER IF EXISTS audit_log_chain ON audit_log;
DROP TRIGGER IF EXISTS audit_log_immutable ON audit_log;
DROP TRIGGER IF EXISTS audit_log_no_truncate ON audit_log;
DROP TRIGGER IF EXISTS privacy_notice_immutable ON privacy_notice;
DROP FUNCTION IF EXISTS audit_log_verify(uuid);
DROP FUNCTION IF EXISTS audit_log_chain();
DROP FUNCTION IF EXISTS reject_change();
DROP FUNCTION IF EXISTS audit_log_digest(bytea, uuid, bigint, uuid, text, text, jsonb, timestamptz);
"""
    )
    for table in (*TENANT_TABLES, "tenant", "tenant_member", "tenant_route"):
        op.execute(f"DROP POLICY IF EXISTS tenant_isolation ON {table}")
    for policy, table in (
        ("member_read", "tenant_member"),
        ("member_write", "tenant_member"),
        ("member_update", "tenant_member"),
        ("member_delete", "tenant_member"),
        ("route_read", "tenant_route"),
        ("route_insert", "tenant_route"),
        ("route_update", "tenant_route"),
        ("route_delete", "tenant_route"),
    ):
        op.execute(f"DROP POLICY IF EXISTS {policy} ON {table}")
    op.execute("DROP FUNCTION IF EXISTS app_current_tenant(); DROP FUNCTION IF EXISTS app_current_user();")
